from _lib import File
F=File('pre2020_deep7','o-d7','Deepening pass 7 for pre-2020 motocross models: second- and third-source dyno sets, fuelled weights and shootout notes for 2013, 2015, 2017, 2018 and 2019 (knowledge push 2026-11)','KTM',['450 SX-F'],list(range(2013,2020)))
R=F.R; K='KTM'; Q='Husqvarna'; H='Honda'; Y='Yamaha'; W='Kawasaki'; M='magazine'
DN='Rear-wheel figures from this source only; dynos differ, so compare within this set.'
def P(src,y,mk,md,st,v,topic): R('power_feel',md+' '+str(y)+' '+topic,[md],[y],st,v,'MEASURED',src,notes=DN,make=mk)
def C(src,y,mk,md,st,v,topic): R('chassis',md+' '+str(y)+' '+topic,[md],[y],st,v,'TUNER',src,make=mk)
s=F.src(M,"Motorcycle.com - 2017 450cc motocross shootout","https://www.motorcycle.com/shoot-outs/2017-450cc-motocross-shootout","2017")
T='third-source dyno, fuelled weight and test notes'
P(s,2017,H,'CRF450R',"A third outlet's 2017 450 test measured the CRF450R at 52.5 hp at 8,900 rpm on its rear-wheel dyno and 246.2 lb fully fuelled. Testers found strong, tractable power that pulls to the limiter, a plush coil fork and a stable, easy-turning chassis, with average brakes; the suspension stayed at stock settings.",{'rwhp':52.5,'rpm':8900,'weight_lb_fuelled':246.2},T)
P(s,2017,Q,'FC 450',"A third outlet's 2017 450 test measured the FC 450 at 54.4 hp at 9,700 rpm on its rear-wheel dyno, the most in the test, and 238.3 lb fully fuelled. It has smooth, strong low-end with good grip and is stable over rough ground, though some riders felt it was slower than its numbers, with vibration and a hard seat.",{'rwhp':54.4,'rpm':9700,'weight_lb_fuelled':238.3},T)
P(s,2017,W,'KX450',"A third outlet's 2017 450 test measured the KX450F at 50.6 hp at 9,000 rpm on its rear-wheel dyno and 242.2 lb fully fuelled. Low-end is clean and lively; the top end and throttle response are weak, shifting is harsh and the fork stiff. The leanest plug-in coupler sharpened throttle response but brought popping on deceleration.",{'rwhp':50.6,'rpm':9000,'weight_lb_fuelled':242.2},T)
R('power_feel','450 SX-F 2017 third-source dyno, fuelled weight and test notes',['450 SX-F'],[2017],"A third outlet's 2017 450 test measured the 450 SX-F (the mid-year Factory Edition) at 52.5 hp at 9,800 rpm on its rear-wheel dyno and 236.3 lb fully fuelled, the lightest in the test, with the best brakes. To cure headshake the testers took eight clicks of compression out of the air fork. They preferred the stock map.",{'rwhp':52.5,'rpm':9800,'weight_lb_fuelled':236.3,'fork_comp':'-8 clicks'},'MEASURED',s,notes='Test bike was the 2017-1/2 Factory Edition. '+DN,make=K)
P(s,2017,Y,'YZ450F',"A third outlet's 2017 450 test measured the YZ450F at 53.3 hp at 9,300 rpm and 33.3 lb-ft at 8,000 rpm on its rear-wheel dyno, the torque leader, and 249.1 lb fully fuelled, the heaviest. It has the strongest-feeling engine and excellent straight-line stability, with heavy steering that pushes wide and a rear brake that locks easily. Testers backed the compression off a few clicks and softened the shock.",{'rwhp':53.3,'rpm':9300,'torque_lbft':33.3,'weight_lb_fuelled':249.1},T)
s=F.src(M,"DirtBikes.com - 2018 450cc motocross shootout","https://dirtbikes.com/2018-450cc-motocross-shootout-whos-the-best/2","2018")
T='third-source dyno and engine notes'
P(s,2018,Y,'YZ450F',"A third outlet's 2018 450 test measured the YZ450F at 52.3 rwhp at 9,900 rpm and 32.0 lb-ft at 7,800 rpm and ranked its engine first: strong and smooth from bottom to top with the best throttle response in the class.",{'rwhp':52.3,'rpm':9900,'torque_lbft':32.0,'torque_rpm':7800},T)
P(s,2018,K,'450 SX-F',"A third outlet's 2018 450 test measured the 450 SX-F at 52.7 rwhp at 10,100 rpm and 32.0 lb-ft at 8,000 rpm. Testers praised the smooth power and exciting top end; low-end pull is softer than some rivals.",{'rwhp':52.7,'rpm':10100,'torque_lbft':32.0,'torque_rpm':8000},T)
P(s,2018,H,'CRF450R',"A third outlet's 2018 450 test measured the CRF450R at 52.9 hp at 9,300 rpm and 33.2 lb-ft at 7,700 rpm: a strong low-end burst and torque that arrives early, with the heaviest clutch pull in the class. One test bike stalled several times and was hard to restart.",{'rwhp':52.9,'rpm':9300,'torque_lbft':33.2,'torque_rpm':7700},T)
P(s,2018,Q,'FC 450',"A third outlet's 2018 450 test measured the FC 450 at 54 rwhp at 9,500 rpm and 33.5 lb-ft at 7,600 rpm, the most power and torque on that dyno, yet testers found it soft, short of snap and less powerful in feel than its numbers.",{'rwhp':54,'rpm':9500,'torque_lbft':33.5,'torque_rpm':7600},T)
P(s,2018,W,'KX450',"A third outlet's 2018 450 test measured the KX450F at 51.8 rwhp at 8,900 rpm and 32.9 lb-ft at 7,800 rpm: good low and mid power, a weak top end and a clunky gearbox. The lean plug-in coupler improved the feel somewhat.",{'rwhp':51.8,'rpm':8900,'torque_lbft':32.9,'torque_rpm':7800},T)
s=F.src(M,"Dirt Bike Magazine - 2015 250F motocross shootout","https://dirtbikemagazine.com/2015-250f-motocross-shootout/","2015")
T='second-opinion shootout notes, weight and price'
C(s,2015,Y,'YZ250F',"A second magazine also ranked the 2015 YZ250F first: the best engine in the class from the bottom through the midrange and the best front suspension, at 222 lb without fuel and $7,590. Most riders ran the suspension without touching the clickers. It has less front-wheel bite when the throttle is chopped, a harsh rev-limiter cut and average brakes. For 2015 it got a new exhaust cam, piston and exhaust valves and revised fork valving.",{'rank':1,'weight_lb_no_fuel':222,'msrp_usd':7590},T)
C(s,2015,W,'KX250',"A second magazine ranked the 2015 KX250F second: a strong, complete powerband with good throttle response, a very adjustable chassis and a well-rated fork and brakes, at 229 lb without fuel and $7,599. The clutch is weak and the exhaust loud. The standard and lean couplers were the testers' favourites.",{'rank':2,'weight_lb_no_fuel':229,'msrp_usd':7599,'couplers':'standard or lean'},T)
C(s,2015,H,'CRF250R',"A second magazine found the 2015 CRF250R light, easy to manage and comfortable for novices at 222 lb without fuel and $7,599, with a larger front disc and a new air fork that works well, but no real power gain and frequent reports of instability. Fork pressure advice: raise the upper chamber for riders over about 165 lb and lower it for those under about 140 lb, and adjust the steering damper before changing air pressure.",{'weight_lb_no_fuel':222,'msrp_usd':7599,'fork_air':'more above 165 lb, less below 140 lb'},T)
C(s,2015,K,'250 SX-F',"A second magazine rated the 2015 250 SX-F the most powerful 250 with a strong top end and predictable handling, at 229 lb without fuel and $8,099. It is weak off the bottom, the 4CS fork is harsh over small bumps and the clutch pull is stiff.",{'weight_lb_no_fuel':229,'msrp_usd':8099},T)
C(s,2015,Q,'FC 250',"A second magazine found the 2015 FC 250's restrictive airbox cost it almost two horsepower against the KTM, and its subframe made it the heaviest 250 at 232 lb without fuel; it listed at $8,149. On its 4CS fork the left-side adjuster only changes high-speed compression, so it does little for small-bump harshness.",{'weight_lb_no_fuel':232,'msrp_usd':8149,'airbox_loss_hp':'almost 2'},T)
s=F.src(M,"Cycle World - 2019 250F MX shootout","https://www.cycleworld.com/2019-250f-mx-shootout","2019")
T='full-tank weight and third-opinion ranking'
C(s,2019,K,'250 SX-F',"A third magazine also ranked the 2019 250 SX-F first of six: the strongest engine, good suspension and a nimble yet stable chassis. It weighed 231 lb with a full tank, the lightest.",{'rank':'1 of 6','weight_lb_full':231},T)
C(s,2019,Q,'FC 250',"A third magazine ranked the 2019 FC 250 second of six: a powerful engine, very good suspension and neutral handling. It weighed 234 lb with a full tank.",{'rank':'2 of 6','weight_lb_full':234},T)
C(s,2019,Y,'YZ250F',"A third magazine ranked the 2019 YZ250F third of six: wide, strong power delivery, plush suspension and great stability. It weighed 236 lb with a full tank.",{'rank':'3 of 6','weight_lb_full':236},T)
C(s,2019,H,'CRF250R',"A third magazine ranked the 2019 CRF250R fourth of six: good suspension, comfortable ergonomics and the nimblest handling in the test. It weighed 239 lb with a full tank, the heaviest of the five.",{'rank':'4 of 6','weight_lb_full':239},T)
C(s,2019,W,'KX250',"A third magazine ranked the 2019 KX250 fifth of six and noted it was carried over from 2018 apart from graphics, shroud colour and the model name. It weighed 232 lb with a full tank.",{'rank':'5 of 6','weight_lb_full':232},T)
s=F.src(M,"Dirt Rider - 2019 KTM 450 SX-F dyno","https://dirtrider.com/2019-ktm-450-sx-f-dyno","2019")
P(s,2019,K,'450 SX-F',"On a second magazine's rear-wheel dyno, run in third gear, the 2019 450 SX-F made 50.79 hp at 9,320 rpm and 32.55 lb-ft at 6,800 rpm.",{'rwhp':50.79,'rpm':9320,'torque_lbft':32.55,'torque_rpm':6800},'second-source dyno')
s=F.src(M,"Dirt Rider - 2019 Kawasaki KX450 dyno","https://dirtrider.com/2019-kawasaki-kx450-dyno","2019")
P(s,2019,W,'KX450',"On a second magazine's rear-wheel dyno the new 2019 KX450 made 52.63 hp at 9,480 rpm and 32.80 lb-ft at 6,730 rpm, with noticeably more power than the earlier engine in every part of the range. The engine has a 44 mm throttle body and larger titanium valves.",{'rwhp':52.63,'rpm':9480,'torque_lbft':32.80,'torque_rpm':6730},'second-source dyno')
s=F.src(M,"Cycle World - 2019 Honda CRF450R dyno","https://cycleworld.com/2019-honda-crf450r-dyno","2019")
P(s,2019,H,'CRF450R',"On a second magazine's rear-wheel dyno, run in third gear, the 2019 CRF450R made 53.75 hp at 9,760 rpm and 33.24 lb-ft at 7,390 rpm, the most power and torque of the six 2019 450s tested there.",{'rwhp':53.75,'rpm':9760,'torque_lbft':33.24,'torque_rpm':7390},'second-source dyno')
s=F.src(M,"Transmoto - 2013 450cc motocross shootout","https://transmoto.com.au/2013-transmoto-450cc-motocross-bike-shootout","2013")
T='second-opinion shootout notes'
C(s,2013,W,'KX450',"A second magazine also named the 2013 KX450F the clear winner on both engine and handling: the broadest, smoothest power and the most compliant ride over small bumps, and no tester bottomed either end in two days. It was the loudest bike and the front can feel vague mid-turn. Dropping 2-3 psi from the air fork helped in tight turns, and the soft map made it more forgiving.",{'fork_air':'-2 to 3 psi for tight turns'},T)
C(s,2013,K,'450 SX-F',"A second magazine found the 2013 450 SX-F had the strongest midrange of five 450s, the lightest controls and the most confidence-inspiring front end, at 109.3 kg with fluids but no fuel, electric start included. It spins the rear on hardpack and has heavy engine braking. Stock gearing is 13/52; a 51- or 50-tooth rear was suggested.",{'weight_kg_no_fuel':109.3,'gearing':'13/52 stock; 51 or 50 rear suggested'},T)
C(s,2013,Y,'YZ450F',"A second magazine found the 2013 YZ450F torquey and stable, holding its line through high-speed hits, at 107.6 kg with fluids but no fuel. The power falls off abruptly at high revs, the throttle is lurchy off idle and it is less agile in tight turns. Less compression damping improved mid-turn feel but upset stability at speed.",{'weight_kg_no_fuel':107.6},T)
C(s,2013,H,'CRF450R',"A second magazine found the 2013 CRF450R the lightest 450 at 106.8 kg with fluids but no fuel and the most agile, but short of low-rev torque and throttle response, with a restrictive exhaust. Adding a few psi to the air fork settled it at speed. Fork pressure rose 4-6 psi within half an hour of riding, so check it between sessions. For 2013 compression went from 12.0 to 12.5:1 and the tank from 5.7 to 6.3 litres.",{'weight_kg_no_fuel':106.8,'fork_air_rise_psi':'4-6 in 30 min','compression':'12.5:1'},T)
if __name__=='__main__': F.write()
